package com.cappleapple.astralrepository.platform.client.extensions.common;
import net.minecraft.world.level.material.Fluid;import net.minecraft.resources.ResourceLocation;import com.cappleapple.astralrepository.platform.fluids.FluidStack;
public record IClientFluidTypeExtensions(Fluid fluid){public static IClientFluidTypeExtensions of(Fluid fluid){return new IClientFluidTypeExtensions(fluid);}public ResourceLocation getStillTexture(){return getStillTexture(new FluidStack(fluid,1000));}public ResourceLocation getFlowingTexture(){var handler=net.fabricmc.fabric.api.client.render.fluid.v1.FluidRenderHandlerRegistry.INSTANCE.get(fluid);if(handler==null)return getStillTexture();var sprites=handler.getFluidSprites(null,null,fluid.defaultFluidState());return sprites.length>1?sprites[1].contents().name():getStillTexture();}public int getTintColor(){return getTintColor(new FluidStack(fluid,1000));}public ResourceLocation getStillTexture(FluidStack stack){var sprite=net.fabricmc.fabric.api.transfer.v1.client.fluid.FluidVariantRendering.getSprite(stack.variant());return sprite==null?ResourceLocation.withDefaultNamespace("missingno"):sprite.contents().name();}public int getTintColor(FluidStack stack){return net.fabricmc.fabric.api.transfer.v1.client.fluid.FluidVariantRendering.getColor(stack.variant());}}
